 r.asset_id=a.id;r.source_sha256=a.sha256;r.reuse=!!isApproved(a,l);
 await DESKReferenceLibrary.post('api/location-production',{location_id:l.id,scope:'scene',scene_key:key(s),source_sha256:l.script_source.sha256,expected:before,plan:draft});
